const stats = $input.first().json;

// Calcul des durées en minutes
const movieMinutes = stats.movies?.minutes || 0;
const episodeMinutes = stats.episodes?.minutes || 0;
const totalMinutes = movieMinutes + episodeMinutes;

// Conversions en heures et en jours
const movieHours = +(movieMinutes / 60).toFixed(1);
const episodeHours = +(episodeMinutes / 60).toFixed(1);
const totalHours = +(totalMinutes / 60).toFixed(1);
const totalDays = +(totalMinutes / 1440).toFixed(2);

// Date de l'enregistrement (format YYYY-MM-DD HH:mm)
const dateEnregistrement = new Date().toISOString().replace('T', ' ').substring(0, 16);

return [{
  json: {
    date: dateEnregistrement,
    user: "YOUR_USERNAME",
    films_vus: stats.movies?.watched || 0,
    films_lectures_totales: stats.movies?.plays || 0,
    films_minutes: movieMinutes,
    films_heures: movieHours,
    series_vues: stats.shows?.watched || 0,
    episodes_vus: stats.episodes?.watched || 0,
    episodes_lectures_totales: stats.episodes?.plays || 0,
    episodes_minutes: episodeMinutes,
    episodes_heures: episodeHours,
    temps_total_minutes: totalMinutes,
    temps_total_heures: totalHours,
    temps_total_jours: totalDays,
    notes_films: stats.movies?.ratings || 0,
    notes_series: stats.shows?.ratings || 0
  }
}];

const items = $input.all();

let countFilms = 0;
let countSeries = 0;
let countSaisons = 0;
let countEpisodes = 0;
let totalEpisodesWatchlist = 0;

// 1. Initialisation des compteurs
const filmsParDecennie = {};
const episodesParDecennie = {};
const filmsParPaysWatchlist = {};
const seriesEpisodesParPaysWatchlist = {};
const filmsParGenreFusionne = {};
const seriesEpisodesParGenreFusionne = {};

// Initialisation des décennies
for (let d = 1890; d <= 2090; d += 10) {
  filmsParDecennie[`${d}s`] = 0;
  episodesParDecennie[`${d}s`] = 0;
}

// Catégories pour les informations manquantes
filmsParDecennie["sans années"] = 0;
episodesParDecennie["sans années"] = 0;

filmsParPaysWatchlist["sans pays"] = 0;
seriesEpisodesParPaysWatchlist["sans pays"] = 0;

// 2. Fonctions utilitaires

/**
 * Retourne la décennie correspondant à une année.
 * Accepte également une année fournie sous forme de chaîne.
 */
function obtenirDecennie(year) {
  if (
    year === null ||
    year === undefined ||
    year === ""
  ) {
    return "sans années";
  }

  const annee = Number(year);

  if (!Number.isFinite(annee) || annee <= 0) {
    return "sans années";
  }

  return `${Math.floor(annee / 10) * 10}s`;
}

/**
 * Normalise le code pays.
 */
function normaliserPays(country) {
  if (typeof country !== "string") {
    return "sans pays";
  }

  const code = country.trim().toLowerCase();

  return code || "sans pays";
}

/**
 * Compte les films par décennie.
 */
function compterFilmsDecennie(year) {
  const decennieKey = obtenirDecennie(year);

  filmsParDecennie[decennieKey] =
    (filmsParDecennie[decennieKey] || 0) + 1;
}

/**
 * Compte les épisodes par décennie.
 */
function compterEpisodesDecennie(year, nbEpisodes) {
  if (nbEpisodes <= 0) return;

  const decennieKey = obtenirDecennie(year);

  episodesParDecennie[decennieKey] =
    (episodesParDecennie[decennieKey] || 0) + nbEpisodes;
}

/**
 * Compte les films par pays.
 */
function compterPaysFilms(country, dict) {
  const code = normaliserPays(country);

  dict[code] = (dict[code] || 0) + 1;
}

/**
 * Compte les épisodes de séries par pays.
 */
function compterPaysSeries(country, nbEpisodes, dict) {
  if (nbEpisodes <= 0) return;

  const code = normaliserPays(country);

  dict[code] = (dict[code] || 0) + nbEpisodes;
}

/**
 * Compte les genres et sous-genres des films.
 */
function compterGenresFilms(movie, dict) {
  if (!movie) return;

  const tousLesGenres = [];

  if (Array.isArray(movie.genres)) {
    tousLesGenres.push(...movie.genres);
  }

  if (Array.isArray(movie.subgenres)) {
    tousLesGenres.push(...movie.subgenres);
  }

  for (const tag of tousLesGenres) {
    dict[tag] = (dict[tag] || 0) + 1;
  }
}

/**
 * Compte les genres et sous-genres des séries,
 * pondérés par le nombre d’épisodes.
 */
function compterGenresSeries(show, nbEpisodes, dict) {
  if (!show || nbEpisodes <= 0) return;

  const tousLesGenres = [];

  if (Array.isArray(show.genres)) {
    tousLesGenres.push(...show.genres);
  }

  if (Array.isArray(show.subgenres)) {
    tousLesGenres.push(...show.subgenres);
  }

  for (const tag of tousLesGenres) {
    dict[tag] = (dict[tag] || 0) + nbEpisodes;
  }
}

// 3. Traitement des éléments
for (const entry of items) {
  const data = entry.json;
  const type = data.type?.toLowerCase();

  switch (type) {
    case "movie": {
      countFilms++;

      compterFilmsDecennie(data.movie?.year);

      compterPaysFilms(
        data.movie?.country,
        filmsParPaysWatchlist
      );

      compterGenresFilms(
        data.movie,
        filmsParGenreFusionne
      );

      break;
    }

    case "show": {
      countSeries++;

      const showEps = data.show?.aired_episodes || 0;

      totalEpisodesWatchlist += showEps;

      compterEpisodesDecennie(
        data.show?.year,
        showEps
      );

      compterPaysSeries(
        data.show?.country,
        showEps,
        seriesEpisodesParPaysWatchlist
      );

      compterGenresSeries(
        data.show,
        showEps,
        seriesEpisodesParGenreFusionne
      );

      break;
    }

    case "season": {
      countSaisons++;

      const seasonEps = data.season?.episode_count || 0;

      totalEpisodesWatchlist += seasonEps;

      compterEpisodesDecennie(
        data.show?.year,
        seasonEps
      );

      compterPaysSeries(
        data.show?.country,
        seasonEps,
        seriesEpisodesParPaysWatchlist
      );

      compterGenresSeries(
        data.show,
        seasonEps,
        seriesEpisodesParGenreFusionne
      );

      break;
    }

    case "episode": {
      countEpisodes++;
      totalEpisodesWatchlist += 1;

      compterEpisodesDecennie(
        data.show?.year,
        1
      );

      compterPaysSeries(
        data.show?.country,
        1,
        seriesEpisodesParPaysWatchlist
      );

      compterGenresSeries(
        data.show,
        1,
        seriesEpisodesParGenreFusionne
      );

      break;
    }

    default: {
      if (data.movie) {
        countFilms++;

        compterFilmsDecennie(
          data.movie?.year
        );

        compterPaysFilms(
          data.movie?.country,
          filmsParPaysWatchlist
        );

        compterGenresFilms(
          data.movie,
          filmsParGenreFusionne
        );
      } else if (data.episode) {
        countEpisodes++;
        totalEpisodesWatchlist += 1;

        compterEpisodesDecennie(
          data.show?.year,
          1
        );

        compterPaysSeries(
          data.show?.country,
          1,
          seriesEpisodesParPaysWatchlist
        );

        compterGenresSeries(
          data.show,
          1,
          seriesEpisodesParGenreFusionne
        );
      } else if (data.show) {
        countSeries++;

        const defaultShowEps =
          data.show?.aired_episodes || 0;

        totalEpisodesWatchlist += defaultShowEps;

        compterEpisodesDecennie(
          data.show?.year,
          defaultShowEps
        );

        compterPaysSeries(
          data.show?.country,
          defaultShowEps,
          seriesEpisodesParPaysWatchlist
        );

        compterGenresSeries(
          data.show,
          defaultShowEps,
          seriesEpisodesParGenreFusionne
        );
      }

      break;
    }
  }
}

// 4. Date d’enregistrement
const dateEnregistrement = new Date()
  .toISOString()
  .replace("T", " ")
  .substring(0, 16);

// 5. Résultat
return [
  {
    json: {
      date: dateEnregistrement,
      user: "YOUR_USERNAME",

      films_a_voir: countFilms,
      series_a_voir: countSeries,
      saisons_a_voir: countSaisons,
      episodes_a_voir: countEpisodes,
      episodes_totaux_a_voir: totalEpisodesWatchlist,
      total_watchlist: items.length,

      films_par_decennie: filmsParDecennie,
      episodes_par_decennie: episodesParDecennie,

      films_par_pays_watchlist:
        filmsParPaysWatchlist,

      series_episodes_par_pays_watchlist:
        seriesEpisodesParPaysWatchlist,

      films_genres_watchlist:
        filmsParGenreFusionne,

      series_episodes_genres_watchlist:
        seriesEpisodesParGenreFusionne
    }
  }
];

const items = $input.all();

let longestMovie = null;
let shortestMovie = null;
let oldestMovie = null;

let maxRuntime = -Infinity;
let minRuntime = Infinity;
let minYear = Infinity;

let totalRuntime = 0;
let validMoviesCount = 0;

let moviesWithoutYear = 0;
let moviesWithoutCountry = 0;

const filmsParDecennieBrut = {};
const filmsParGenreFusionne = {};
const filmsParPays = {};

function formatMovieString(movie, runtime) {
  if (!movie) return "";

  const hours = Math.floor(runtime / 60);
  const minutes = runtime % 60;

  if (hours > 0) {
    return `${movie.title} (${hours} h ${minutes} min)`;
  }

  return `${movie.title} (${minutes} min)`;
}

for (const item of items) {
  const data = item.json;

  // Supports { movie: {...} } and direct movie objects.
  const movie = data.movie || data;

  if (!movie || !movie.title) continue;

  const runtime = movie.runtime;
  const year = movie.year;
  const country = movie.country;

  // 1. Movies by country
  if (typeof country === "string" && country.trim() !== "") {
    const countryCode = country.trim().toLowerCase();

    filmsParPays[countryCode] =
      (filmsParPays[countryCode] || 0) + 1;
  } else {
    moviesWithoutCountry++;
  }

  // 2. Genres and subgenres
  const allGenres = [];

  if (Array.isArray(movie.genres)) {
    allGenres.push(...movie.genres);
  }

  if (Array.isArray(movie.subgenres)) {
    allGenres.push(...movie.subgenres);
  }

  for (const tag of allGenres) {
    filmsParGenreFusionne[tag] =
      (filmsParGenreFusionne[tag] || 0) + 1;
  }

  // 3. Runtime calculations
  if (typeof runtime === "number" && runtime > 0) {
    validMoviesCount++;
    totalRuntime += runtime;

    if (runtime > maxRuntime) {
      maxRuntime = runtime;
      longestMovie = movie;
    }

    if (runtime < minRuntime) {
      minRuntime = runtime;
      shortestMovie = movie;
    }
  }

  // 4. Year and decade calculations
  const normalizedYear =
    year !== null &&
    year !== undefined &&
    year !== ""
      ? Number(year)
      : NaN;

  if (
    Number.isFinite(normalizedYear) &&
    normalizedYear > 0
  ) {
    if (normalizedYear < minYear) {
      minYear = normalizedYear;
      oldestMovie = movie;
    }

    const decade = Math.floor(normalizedYear / 10) * 10;
    const decadeKey = `${decade}s`;

    filmsParDecennieBrut[decadeKey] =
      (filmsParDecennieBrut[decadeKey] || 0) + 1;
  } else {
    moviesWithoutYear++;
  }
}

if (validMoviesCount === 0 && !oldestMovie) {
  return [
    {
      json: {
        message: "Aucun film valide trouvé"
      }
    }
  ];
}

// Fill decades chronologically.
const filmsParDecennie = {};

const foundYears = Object.keys(filmsParDecennieBrut)
  .map(key => parseInt(key, 10))
  .filter(Number.isFinite);

const minDecade =
  foundYears.length > 0
    ? Math.min(...foundYears)
    : 1890;

const maxDecade = 2090;

for (
  let decade = minDecade;
  decade <= maxDecade;
  decade += 10
) {
  const decadeKey = `${decade}s`;

  filmsParDecennie[decadeKey] =
    filmsParDecennieBrut[decadeKey] || 0;
}

// Add missing-information categories at the end.
filmsParDecennie["sans années"] = moviesWithoutYear;
filmsParPays["sans pays"] = moviesWithoutCountry;

// Average runtime
const averageRuntimeMinutes =
  validMoviesCount > 0
    ? Math.round(totalRuntime / validMoviesCount)
    : 0;

const averageHours = Math.floor(
  averageRuntimeMinutes / 60
);

const averageMinutes =
  averageRuntimeMinutes % 60;

const formattedAverage =
  averageHours > 0
    ? `${averageHours} h ${averageMinutes} min`
    : `${averageMinutes} min`;

return [
  {
    json: {
      user: "YOUR_USERNAME",

      film_plus_long: formatMovieString(
        longestMovie,
        maxRuntime
      ),

      film_plus_court: formatMovieString(
        shortestMovie,
        minRuntime
      ),

      film_plus_vieux: oldestMovie
        ? `${oldestMovie.title} (${oldestMovie.year})`
        : null,

      moyenne_films: formattedAverage,
      moyenne_minutes: averageRuntimeMinutes,
      total_films_analyses: validMoviesCount,

      films_par_decennie: filmsParDecennie,
      films_par_pays: filmsParPays,
      genres_et_sous_genres: filmsParGenreFusionne
    }
  }
];

const items = $input.all();

let longestEpisode = null;
let maxRuntime = 0;

let shortestEpisode = null;
let minRuntime = Infinity;

let totalRuntime = 0;
let validEpisodesCount = 0;

let episodesWithoutYear = 0;
let episodesWithoutCountry = 0;

// 1. Initialize decade counters.
const episodesParDecennie = {};

for (let decade = 1890; decade <= 2090; decade += 10) {
  episodesParDecennie[`${decade}s`] = 0;
}

const episodesParGenreFusionne = {};
const episodesParPays = {};

for (const item of items) {
  const data = item.json;
  const episode = data.episode;
  const show = data.show;

  // 2. Episodes by series country
  const country = show?.country;

  if (typeof country === "string" && country.trim() !== "") {
    const countryCode = country.trim().toLowerCase();

    episodesParPays[countryCode] =
      (episodesParPays[countryCode] || 0) + 1;
  } else {
    episodesWithoutCountry++;
  }

  // 3. Episodes by series decade
  const year = show?.year;

  const normalizedYear =
    year !== null &&
    year !== undefined &&
    year !== ""
      ? Number(year)
      : NaN;

  if (
    Number.isFinite(normalizedYear) &&
    normalizedYear > 0
  ) {
    const decade =
      Math.floor(normalizedYear / 10) * 10;

    const decadeKey = `${decade}s`;

    episodesParDecennie[decadeKey] =
      (episodesParDecennie[decadeKey] || 0) + 1;
  } else {
    episodesWithoutYear++;
  }

  // 4. Genres and subgenres
  const allGenres = [];

  if (Array.isArray(show?.genres)) {
    allGenres.push(...show.genres);
  }

  if (Array.isArray(show?.subgenres)) {
    allGenres.push(...show.subgenres);
  }

  for (const tag of allGenres) {
    episodesParGenreFusionne[tag] =
      (episodesParGenreFusionne[tag] || 0) + 1;
  }

  const runtime = Number(episode?.runtime) || 0;

  // 5. Runtime calculations
  if (runtime > 0) {
    totalRuntime += runtime;
    validEpisodesCount++;

    const episodeData = {
      serie: show?.title || "Série inconnue",
      saison: episode?.season ?? 0,
      numero: episode?.number ?? 0,
      titre: episode?.title || "Sans titre",
      runtime
    };

    if (runtime > maxRuntime) {
      maxRuntime = runtime;
      longestEpisode = episodeData;
    }

    if (runtime < minRuntime) {
      minRuntime = runtime;
      shortestEpisode = episodeData;
    }
  }
}

// Add missing-information categories at the end.
episodesParDecennie["sans années"] =
  episodesWithoutYear;

episodesParPays["sans pays"] =
  episodesWithoutCountry;

if (
  !longestEpisode ||
  !shortestEpisode ||
  validEpisodesCount === 0
) {
  return [
    {
      json: {
        message:
          "Aucun épisode avec durée valide trouvé."
      }
    }
  ];
}

// Average runtime rounded to the nearest minute.
const averageRuntime = Math.round(
  totalRuntime / validEpisodesCount
);

function formatDuration(runtime) {
  const hours = Math.floor(runtime / 60);
  const minutes = runtime % 60;

  return hours > 0
    ? `${hours} h ${
        minutes > 0 ? `${minutes} min` : ""
      }`.trim()
    : `${minutes} min`;
}

function formatEpisodeInfo(episodeData) {
  const formattedDuration = formatDuration(
    episodeData.runtime
  );

  const seasonString = String(
    episodeData.saison
  ).padStart(2, "0");

  const episodeString = String(
    episodeData.numero
  ).padStart(2, "0");

  const episodeCode =
    `S${seasonString}E${episodeString}`;

  return {
    serie: episodeData.serie,
    code_episode: episodeCode,
    titre_episode: episodeData.titre,
    duree_minutes: episodeData.runtime,
    duree_formatee: formattedDuration,

    affichage_complet:
      `${episodeData.serie} ` +
      `(${episodeCode} - ${episodeData.titre}) : ` +
      formattedDuration
  };
}

return [
  {
    json: {
      user: "YOUR_USERNAME",

      plus_long:
        formatEpisodeInfo(longestEpisode),

      plus_court:
        formatEpisodeInfo(shortestEpisode),

      moyenne: {
        duree_minutes: averageRuntime,
        duree_formatee:
          formatDuration(averageRuntime),

        base_de_calcul:
          `${validEpisodesCount} épisodes pris en compte`
      },

      episodes_par_decennie:
        episodesParDecennie,

      episodes_par_pays:
        episodesParPays,

      genres_et_sous_genres:
        episodesParGenreFusionne
    }
  }
];

// Code in JavaScript16
// Mode: Run Once for All Items.
//
// Before running, update the Film Data Table:
// Keep: movie_uuid, movie_name, runtime_minutes.
// Remove: watched_at, imdb_id, movie_raw_json, sync_run_at.
// Add: Statut (String).
// Insert row: Map Automatically.

function readSource(nodeName) {
  const entries = [];

  function visit(value) {
    if (value === null || value === undefined) return;

    if (typeof value === 'string') {
      if (value.trim()) visit(JSON.parse(value));
      return;
    }

    if (Array.isArray(value)) {
      for (const entry of value) visit(entry);
      return;
    }

    if (typeof value !== 'object') {
      throw new Error(`${nodeName}: invalid JSON response.`);
    }

    if (Object.keys(value).length === 0) return;

    if (value.error || Number(value.statusCode) >= 400) {
      throw new Error(`${nodeName}: API error.`);
    }

    if (value.movie || value.show) {
      entries.push(value);
      return;
    }

    for (const key of ['body', 'data', 'items', 'results']) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        visit(value[key]);
        return;
      }
    }

    throw new Error(`${nodeName}: unrecognized response format.`);
  }

  for (const item of $(nodeName).all()) {
    visit(item.json);
  }

  return entries;
}

function mediaKey(media, kind) {
  const ids = media.ids || {};

  for (const provider of ['trakt', 'imdb', 'tmdb', 'tvdb', 'slug']) {
    const value = ids[provider];

    if (
      value !== null &&
      value !== undefined &&
      String(value).trim()
    ) {
      return `${provider}:${kind}:${String(value).trim()}`;
    }
  }

  if (ids.plex?.guid) {
    return `plex:${kind}:${ids.plex.guid}`;
  }

  throw new Error(
    `Missing ${kind} identifier: ${media.title || 'unknown'}.`
  );
}

function nonNegativeNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number) && number >= 0
    ? number
    : null;
}

const movies = new Map();

function addMovie(movie, watched) {
  if (!movie || typeof movie !== 'object') {
    throw new Error('Missing movie in a Trakt history entry.');
  }

  const key = mediaKey(movie, 'movie');
  const updatedAt = Date.parse(movie.updated_at) || 0;
  const runtime = nonNegativeNumber(movie.runtime);
  const title = movie.title || movie.original_title || null;

  if (!movies.has(key)) {
    movies.set(key, {
      key,
      title,
      runtime,
      updatedAt,
      watched: Boolean(watched),
    });

    return;
  }

  const current = movies.get(key);

  // Watched takes priority when a movie appears in both sources.
  current.watched = current.watched || watched;

  if (updatedAt >= current.updatedAt) {
    current.title = title || current.title;
    current.runtime = runtime ?? current.runtime;
    current.updatedAt = updatedAt;
  } else {
    current.title = current.title || title;
    current.runtime = current.runtime ?? runtime;
  }
}

for (const entry of readSource('Trakt API - Get Stats1')) {
  if (entry.movie) {
    addMovie(entry.movie, false);
  }
}

for (const entry of readSource('Trakt API - Get Stats2')) {
  addMovie(entry.movie, true);
}

// One row per movie. Empty sources produce no insertable rows.
return [...movies.values()]
  .sort((a, b) =>
    a.key.localeCompare(b.key, 'en', { numeric: true })
  )
  .map(movie => ({
    json: {
      movie_uuid: movie.key,
      movie_name: movie.title || movie.key,
      runtime_minutes: movie.runtime,
      Statut: movie.watched ? 'Vu' : 'Watchlist',
    },
  }));

